spec.rawSql:
select lpad(h::text, 2, '0') || ':00' as "Hour", "Production", "Consumption", "Grid import"
from (
  select extract(hour from time at time zone 'Europe/Vienna')::int as h,
         avg(energy_produced) as "Production",
         avg(energy_used) as "Consumption",
         avg(energy_consumed) as "Grid import"
  from agg_1h_energy_priced where $__timeFilter(time) and metered
  group by 1
) x
order by h;
